CREATE TABLE eta_model_version ("prediction_version" VARCHAR NOT NULL,"training_cutoff_at" TIMESTAMPTZ NOT NULL,"feature_definition_version" VARCHAR NOT NULL,"nominal_interval_coverage" DECIMAL(7,6) NOT NULL,"split_version" VARCHAR NOT NULL,"interval_calibration_version" VARCHAR NOT NULL,"probability_calibration_version" VARCHAR NOT NULL,"calibration_cutoff_at" TIMESTAMPTZ NOT NULL,"baseline_definition" VARCHAR NOT NULL,PRIMARY KEY (prediction_version));

CREATE TABLE p06_model_binding ("tenant_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"source_bindings" JSON NOT NULL,PRIMARY KEY (tenant_id,prediction_version),UNIQUE (prediction_version),FOREIGN KEY (prediction_version) REFERENCES eta_model_version (prediction_version));

CREATE TABLE p06_source_trip ("tenant_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"vehicle_id" VARCHAR NOT NULL,"route_id" VARCHAR NOT NULL,"departure_time" TIMESTAMPTZ NOT NULL,"unseen_vehicle" BOOLEAN NOT NULL,"unseen_route" BOOLEAN NOT NULL,PRIMARY KEY (tenant_id,trip_id));

CREATE TABLE p06_provenance_reference ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"reference_kind" VARCHAR NOT NULL,"source_reference" VARCHAR NOT NULL,"source_sha256" VARCHAR NOT NULL,"record_key" JSON NOT NULL,"parent_provenance_ids" JSON NOT NULL,"recorded_at" TIMESTAMPTZ NOT NULL,PRIMARY KEY (tenant_id,provenance_id));

CREATE TABLE p06_source_snapshot ("tenant_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_time" TIMESTAMPTZ NOT NULL,"promise_version_id" VARCHAR NOT NULL,"deadline_at" TIMESTAMPTZ NOT NULL,"promise_known_at" TIMESTAMPTZ NOT NULL,"snapshot_provenance_id" VARCHAR NOT NULL,"promise_provenance_id" VARCHAR NOT NULL,PRIMARY KEY (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,trip_id) REFERENCES p06_source_trip (tenant_id,trip_id),FOREIGN KEY (tenant_id,snapshot_provenance_id) REFERENCES p06_provenance_reference (tenant_id,provenance_id),FOREIGN KEY (tenant_id,promise_provenance_id) REFERENCES p06_provenance_reference (tenant_id,provenance_id));

CREATE TABLE eta_evaluation_membership ("tenant_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"split_version" VARCHAR NOT NULL,"lead_time_slice" VARCHAR NOT NULL,"unseen_route" BOOLEAN NOT NULL,"trip_evaluation_weight" DECIMAL(12,9) NOT NULL,"evaluation_slice" JSON NOT NULL,PRIMARY KEY (tenant_id,snapshot_id,split_version),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p06_source_snapshot (tenant_id,snapshot_id));

CREATE TABLE eta_prediction ("tenant_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"eta_median" TIMESTAMPTZ NOT NULL,"eta_lower" TIMESTAMPTZ NOT NULL,"eta_upper" TIMESTAMPTZ NOT NULL,"delay_probability" DECIMAL(7,6),"fallback_reason" VARCHAR NOT NULL,"remaining_eta_seconds" BIGINT NOT NULL,"generated_at" TIMESTAMPTZ NOT NULL,"value_states" JSON NOT NULL,PRIMARY KEY (tenant_id,snapshot_id,prediction_version),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p06_source_snapshot (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,prediction_version) REFERENCES p06_model_binding (tenant_id,prediction_version));

CREATE TABLE p06_rule_audit ("policy_version" VARCHAR NOT NULL,"enabled" BOOLEAN NOT NULL,"threshold" DECIMAL(7,6),"selection_status" VARCHAR NOT NULL,"experimental" BOOLEAN NOT NULL,"quality_limits" JSON NOT NULL,"rule" JSON NOT NULL,"selection_manifest" JSON NOT NULL,PRIMARY KEY (policy_version));

CREATE TABLE eta_alert_rule_version ("decision_threshold_version" VARCHAR NOT NULL,"delay_alert_threshold" DECIMAL(7,6) NOT NULL,"minimum_action_lead_seconds" INTEGER NOT NULL,"repeat_suppression_seconds" INTEGER NOT NULL,"threshold_selection_ref" VARCHAR NOT NULL,PRIMARY KEY (decision_threshold_version),FOREIGN KEY (decision_threshold_version) REFERENCES p06_rule_audit (policy_version));

CREATE TABLE p06_opportunity_audit ("tenant_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"snapshot_time" TIMESTAMPTZ NOT NULL,"prediction_version" VARCHAR NOT NULL,"output_id" VARCHAR NOT NULL,"eta_status" VARCHAR NOT NULL,"probability_status" VARCHAR NOT NULL,"probability" DECIMAL(7,6),"lower_seconds" DOUBLE,"median_seconds" DOUBLE,"upper_seconds" DOUBLE,"lower_seconds_int" BIGINT,"median_seconds_int" BIGINT,"upper_seconds_int" BIGINT,"canonical_prediction_written" BOOLEAN NOT NULL,"generated_at" TIMESTAMPTZ NOT NULL,"opportunity" JSON NOT NULL,PRIMARY KEY (tenant_id,snapshot_id,prediction_version),UNIQUE (tenant_id,output_id),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p06_source_snapshot (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,prediction_version) REFERENCES p06_model_binding (tenant_id,prediction_version));

CREATE TABLE eta_output_release ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"output_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"released_at" TIMESTAMPTZ NOT NULL,"release_mode" VARCHAR NOT NULL,PRIMARY KEY (tenant_id,output_id),FOREIGN KEY (tenant_id,output_id) REFERENCES p06_opportunity_audit (tenant_id,output_id),FOREIGN KEY (tenant_id,prediction_version) REFERENCES p06_model_binding (tenant_id,prediction_version),FOREIGN KEY (tenant_id,provenance_id) REFERENCES p06_provenance_reference (tenant_id,provenance_id));

CREATE TABLE p06_episode_audit ("tenant_id" VARCHAR NOT NULL,"episode_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"policy_version" VARCHAR NOT NULL,"research_episode" JSON NOT NULL,PRIMARY KEY (tenant_id,episode_id),FOREIGN KEY (tenant_id,trip_id) REFERENCES p06_source_trip (tenant_id,trip_id),FOREIGN KEY (policy_version) REFERENCES p06_rule_audit (policy_version));

CREATE TABLE p06_candidate_audit ("tenant_id" VARCHAR NOT NULL,"candidate_id" VARCHAR NOT NULL,"episode_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"output_id" VARCHAR NOT NULL,"policy_version" VARCHAR NOT NULL,"simulated_issue_at" TIMESTAMPTZ NOT NULL,"probability" DECIMAL(7,6) NOT NULL,"created_at" TIMESTAMPTZ NOT NULL,"research_candidate" JSON NOT NULL,PRIMARY KEY (tenant_id,candidate_id),FOREIGN KEY (tenant_id,episode_id) REFERENCES p06_episode_audit (tenant_id,episode_id),FOREIGN KEY (tenant_id,output_id) REFERENCES eta_output_release (tenant_id,output_id),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p06_source_snapshot (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,prediction_version) REFERENCES p06_model_binding (tenant_id,prediction_version),FOREIGN KEY (policy_version) REFERENCES p06_rule_audit (policy_version));

CREATE TABLE p06_decision_audit ("tenant_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"snapshot_time" TIMESTAMPTZ NOT NULL,"prediction_version" VARCHAR NOT NULL,"policy_version" VARCHAR NOT NULL,"candidate_status" VARCHAR NOT NULL,"candidate_id" VARCHAR,"episode_id" VARCHAR,"lead_seconds" DOUBLE NOT NULL,"probability" DECIMAL(7,6),"reason" VARCHAR NOT NULL,"decision" JSON NOT NULL,PRIMARY KEY (tenant_id,snapshot_id,prediction_version,policy_version),FOREIGN KEY (tenant_id,snapshot_id) REFERENCES p06_source_snapshot (tenant_id,snapshot_id),FOREIGN KEY (tenant_id,prediction_version) REFERENCES p06_model_binding (tenant_id,prediction_version),FOREIGN KEY (policy_version) REFERENCES p06_rule_audit (policy_version),FOREIGN KEY (tenant_id,candidate_id) REFERENCES p06_candidate_audit (tenant_id,candidate_id),FOREIGN KEY (tenant_id,episode_id) REFERENCES p06_episode_audit (tenant_id,episode_id));

CREATE TABLE eta_alert_episode ("tenant_id" VARCHAR NOT NULL,"alert_episode_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"episode_started_at" TIMESTAMPTZ NOT NULL,"episode_closed_at" TIMESTAMPTZ,"delivered_alert_count" INTEGER NOT NULL,"duplicate_alert_count" INTEGER NOT NULL,"counts_as_of" TIMESTAMPTZ NOT NULL,"value_states" JSON NOT NULL,PRIMARY KEY (tenant_id,alert_episode_id));

CREATE TABLE eta_alert ("tenant_id" VARCHAR NOT NULL,"alert_id" VARCHAR NOT NULL,"alert_episode_id" VARCHAR NOT NULL,"output_id" VARCHAR NOT NULL,"trip_id" VARCHAR NOT NULL,"snapshot_id" VARCHAR NOT NULL,"prediction_version" VARCHAR NOT NULL,"decision_threshold_version" VARCHAR NOT NULL,"created_at" TIMESTAMPTZ NOT NULL,"alert_status" VARCHAR NOT NULL,PRIMARY KEY (tenant_id,alert_id));

CREATE TABLE eta_notification_delivery ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"delivery_id" VARCHAR NOT NULL,"alert_id" VARCHAR NOT NULL,"recipient_role" VARCHAR NOT NULL,"delivered_at" TIMESTAMPTZ,"received_or_opened_at" TIMESTAMPTZ,"receipt_type" VARCHAR NOT NULL,"delivery_status" VARCHAR NOT NULL,PRIMARY KEY (tenant_id,delivery_id));

CREATE TABLE eta_adoption ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"adoption_id" VARCHAR NOT NULL,"delivery_id" VARCHAR NOT NULL,"adoption_status" VARCHAR NOT NULL,"adoption_reason" VARCHAR,"decided_at" TIMESTAMPTZ,PRIMARY KEY (tenant_id,adoption_id));

CREATE TABLE eta_action ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"action_id" VARCHAR NOT NULL,"adoption_id" VARCHAR NOT NULL,"alert_id" VARCHAR NOT NULL,"action_type" VARCHAR NOT NULL,"action_time" TIMESTAMPTZ,"handling_seconds" INTEGER,PRIMARY KEY (tenant_id,action_id));

CREATE TABLE eta_action_followup ("tenant_id" VARCHAR NOT NULL,"provenance_id" VARCHAR NOT NULL,"action_id" VARCHAR NOT NULL,"outcome_version_id" VARCHAR NOT NULL,"followup_promise_version_id" VARCHAR NOT NULL,"original_promise_version_id" VARCHAR NOT NULL,"outcome_observation_end" TIMESTAMPTZ NOT NULL,"observed_delay_seconds" BIGINT,"original_promise_delay_seconds" BIGINT,"review_outcome" VARCHAR NOT NULL,"result_origin" VARCHAR NOT NULL,PRIMARY KEY (tenant_id,action_id,outcome_version_id));
